/bin/zsh -lc "node --input-type=module <<'NODE'
import { createCheckout } from './src/index.mjs';
for (const initial of [[], true, 1, '', { acme: [] }, { acme: 1 }, { acme: 'x' }]) {
  try { console.log('accepted inventory', JSON.stringify(initial), createCheckout(initial).snapshot()); }
  catch (error) { console.log('rejected inventory', JSON.stringify(initial), error.message); }
}
const fields = { tenantId: 'acme', orderId: 'o1', sku: 'widget', quantity: 1, idempotencyKey: 'k1' };
for (const request of [Object.assign(new Date(), fields), Object.assign(() => {}, fields), Object.create(fields)]) {
  const system = createCheckout({ acme: { widget: 1 } });
  try { console.log('accepted nonplain request', await system.checkout(request), system.snapshot()); }
  catch (error) { console.log('rejected nonplain request', error.message); }
}
const payload = new Array(1);
payload.extra = 'value';
const system = createCheckout({ acme: { widget: 1 } });
try { console.log('accepted sparse array', await system.checkout({ ...fields, payload })); }
catch (error) { console.log('rejected sparse array', error.message); }
NODE"

