/bin/zsh -lc "node --input-type=module <<'NODE'
import { createCheckout } from './src/index.mjs';
const request = { tenantId: 'acme', orderId: 'o1', sku: 'widget', quantity: 1, idempotencyKey: 'k1' };
for (const initial of [[], 7, { acme: [] }, { acme: 7 }]) {
  try {
    console.log('accepted invalid inventory', JSON.stringify(initial), createCheckout(initial).snapshot());
  } catch (error) {
    console.log('rejected', error.message);
  }
}
const system = createCheckout({ acme: { widget: 1 } });
try {
  console.log('inherited request result', await system.checkout(Object.create(request)));
  console.log('snapshot after inherited request', system.snapshot());
} catch (error) {
  console.log('inherited request rejected', error.message);
}
const payload = new Array(1);
payload.extra = 'value';
try {
  console.log('invalid sparse payload result', await createCheckout({ acme: { widget: 1 } }).checkout({ ...request, payload }));
} catch (error) {
  console.log('invalid sparse payload rejected', error.message);
}
NODE"
